<script>
  document.querySelectorAll('a[href^="#add-"]').forEach((trigger) => {
    trigger.addEventListener('click', (event) => {
      const panel = document.querySelector(trigger.getAttribute('href'));
      if (!panel || panel.tagName.toLowerCase() !== 'details') return;
      event.preventDefault();
      panel.open = true;
      panel.scrollIntoView({ behavior: 'smooth', block: 'start' });
      const firstField = panel.querySelector('input, select, textarea, button');
      if (firstField) {
        setTimeout(() => firstField.focus({ preventScroll: true }), 250);
      }
    });
  });
</script>
